428	   428	  const options = Array.isArray(r.options) ? [...new Set(r.options.map((o) => str(o, 80)).filter((o) => o && o !== RECOMMEND))].slice(0, 5) : [];
429	   429	  const ok = TRACK_KEYS.includes(track) && track !== blocked && /[?？]$/.test(question) && options.length >= 2;
430	   430	  return { q: ok ? { track, question, hint: str(r.hint, 200), options, multi: r.multi === true, allow_free: r.allow_free !== false } : null, ledger, done };
